import { createReadStream } from 'node:fs';
import { mkdir, readFile, rename, rm, stat } from 'node:fs/promises';
import path from 'node:path';
import { AppError } from '../utils/AppError.js';

// Keys are generated by us (users/<id>/<uuid>.pdf), never from user input — this is defense in depth.
const KEY_PATTERN = /^[\w-]+(\/[\w-]+)*\.pdf$/;

export class LocalStorage {
  constructor(root) {
    this.root = root;
  }

  #resolve(key) {
    if (!KEY_PATTERN.test(key)) throw new Error(`Invalid storage key: ${key}`);
    const fullPath = path.resolve(this.root, key);
    if (!fullPath.startsWith(this.root + path.sep)) throw new Error('Storage key escapes root');
    return fullPath;
  }

  /** Moves a file into storage. Multer's temp dir lives inside root, so rename is an atomic same-disk move. */
  async putFile(key, sourcePath) {
    const target = this.#resolve(key);
    await mkdir(path.dirname(target), { recursive: true });
    await rename(sourcePath, target);
  }

  async openReadStream(key) {
    const target = this.#resolve(key);
    try {
      const { size } = await stat(target); // fail with a clean 404 before any headers are sent
      return { stream: createReadStream(target), size };
    } catch (err) {
      if (err.code === 'ENOENT') throw new AppError('NOT_FOUND', { message: 'File not found' });
      throw err;
    }
  }

  async getBuffer(key) {
    try {
      return await readFile(this.#resolve(key));
    } catch (err) {
      if (err.code === 'ENOENT') throw new AppError('NOT_FOUND', { message: 'File not found' });
      throw err;
    }
  }

  async remove(key) {
    await rm(this.#resolve(key), { force: true });
  }
}
